/**
 * KnownChains
 *
 * EVM-compatible blockchain networks the codebase knows about.
 *
 * This is a *vocabulary* enum — the set of chain IDs the code can talk about
 * for asset metadata, off-ramp routing (Meld), payment-link acceptance, and
 * agent data lookups. It is NOT an acceptance enum: typing a request-model
 * field as `chain_id: KnownChains` does NOT gate input to operational chains.
 *
 * For write-boundary acceptance (onboarding, wallet creation, workflow
 * contracts), use `DeployableChain` from `sumvin/model/enums/chain.py`.
 *
 * Chain ID values follow the EIP-155 standard.
 *
 * - `1` - Ethereum Mainnet
 * - `10` - Optimism
 * - `137` - Polygon (formerly Matic)
 * - `42161` - Arbitrum One
 * - `8453` - Base
 * - `43114` - Avalanche C-Chain
 * - `56` - BNB Smart Chain (BSC)
 * - `1328` - Sei Testnet
 * - `1329` - Sei
 */
export type KnownChains = 1 | 10 | 137 | 42161 | 8453 | 43114 | 56 | 1328 | 1329;

