/**
 * OnboardingOrigin
 *
 * Which product surface the user entered onboarding through.
 *
 * Orthogonal to `SafeOnboardingMode`: that answers *how the Safe is created*,
 * this answers *where the user came from*. Both narrow which steps a user's
 * flow contains, and both are write-once.
 *
 * - APP: the web app. Every step the user's org and feature gates leave open.
 * - CLI: the terminal. The flow terminates at `KYC_VERIFICATION` — a
 * terminal-only client has nothing to render for bank linking, card
 * issuance or feature opt-in.
 * - AGENT: the agent lane. Same two-step flow as CLI — a headless agent has
 * nothing to render past identity verification — but a different
 * *provisioning* answer: the user holds no EOA at creation, so the Safe is
 * deployed after KYC rather than at signup, owned solely by the signer
 * proxy until a bound Para key is added as a second owner.
 *
 * `users.onboarding_origin` is nullable and NULL means APP, mirroring
 * `safe_mode`: every row predating the column keeps the flow it already had,
 * with no backfill.
 */
export type OnboardingOrigin = 'app' | 'cli' | 'agent';

/**
 * OnboardingSafeResponse
 *
 * Response for GET/POST /v0/user/me/onboarding/safe.
 *
 * The ``mode`` field selects which Safe-onboarding flow applies to the
 * user. The ``config`` field always carries the cohort-specific data
 * the client needs to render or complete the step — its shape matches
 * ``mode`` (clients switch once on ``config.mode`` and read inner
 * fields, which may be null when no work is currently prepared). The
 * ``wallet`` field is populated once the Safe has been persisted; null
 * otherwise.
 */
export type OnboardingSafeResponse = {
    /**
     * Links
     *
     * HAL-style hypermedia links for navigation and available actions.
     */
    _links: {
        [key: string]: Link;
    };
    /**
     * Which Safe-onboarding flow applies. 'user_signed_deploy' when the user signs the deploy UserOp; 'byo' when the user submits an existing Safe address; 'agent_create2' when the agent signer workflow handles deployment.
     */
    mode: SafeOnboardingMode;
    /**
     * Config
     *
     * Cohort-specific data the client needs to render or complete the step. ``config.mode`` matches the top-level ``mode``; inner fields may be null when no work is currently prepared (e.g., a user_signed_deploy config before the server prepares a UserOp).
     */
    config: ({
        mode: 'user_signed_deploy';
    } & UserSignedDeployData) | ({
        mode: 'byo';
    } & ByoConfigData) | ({
        mode: 'agent_create2';
    } & AgentCreate2ConfigData);
    /**
     * Persisted Safe wallet. Populated once the wallet row exists (PENDING for user-signed-deploy after submit; COMPLETED for BYO; set by the signer workflow for agent_create2). Null otherwise.
     */
    wallet?: WalletData | null;
    /**
     * Chain Id
     *
     * Chain ID on which the Safe must reside. Null when the user has not yet selected a primary chain (e.g., partway through onboarding before chain selection is persisted).
     */
    chain_id?: number | null;
    /**
     * Required
     *
     * True when the user still needs to act on this step. False once the step is completed, skipped, or does not apply to this user.
     */
    required: boolean;
    /**
     * Status of this onboarding step.
     */
    step_status: OnboardingStepStatus;
};

/**
 * OnboardingStep
 *
 * Steps surfaced in the onboarding state machine.
 *
 * Every step below CREATED and above COMPLETE occupies a fixed slot in one
 * presentation order shared by all users. A user's cohort — driven by
 * `org_id` and the `SISFeature` flags configured on the org — decides which
 * of those steps their flow *contains*, and their organisation's features
 * decide which of those are waived. Neither ever changes what a stored step
 * value means, so a step's identity is independent of who is looking at it.
 *
 * - CREATED: User row created; entry point for every cohort. A sentinel
 * outside the order — no user ever stands on it as a step to complete.
 * - PHONE_VERIFICATION: Prelude-based phone code verification.
 * - KYC_VERIFICATION: Identity verification via SumSub. Render mode is
 * surfaced on `meta.kyc_mode` (see `KYCMode`).
 * - BYO_SAFE: Bring Your Own Safe — user submits an existing on-chain Safe
 * address rather than deploying a new one. In the flow when `org_id` is
 * set, `AI_AGENT` is disabled, AND `USER_SIGNED_DEPLOY` is disabled. For
 * partners with existing Safe infrastructure.
 * - SAFE_DEPLOY: User-signed Safe deploy — user signs the Safe deployment
 * UserOp themselves; Sumvin sponsors gas via Pimlico. In the flow when
 * `org_id` is set, `AI_AGENT` is disabled, AND `USER_SIGNED_DEPLOY` is
 * enabled. **Recommended non-default cohort** for partners who want
 * user-controlled Safes without an agent signer.
 * - OPEN_BANKING: Bank-account linking (Meld).
 * - CARD_SETUP: Card issuance and activation.
 * - FEATURE_SELECTION: Final feature opt-in (insights, strategies, etc.).
 * - COMPLETE: Terminal state — reached once every step the user's flow
 * requires is done. Also a sentinel outside the order.
 *
 * Note: `BYO_SAFE` and `SAFE_DEPLOY` are mutually exclusive — they occupy the
 * same slot, and no flow contains both. The default Sumvin cohort (no
 * `org_id`, or `AI_AGENT` enabled) contains neither: Sumvin's signing service
 * deploys the Safe and attaches an agent signer, so there is no user step.
 */
export type OnboardingStep = 'created' | 'phone_verification' | 'kyc_verification' | 'byo_safe' | 'safe_deploy' | 'open_banking' | 'card_setup' | 'feature_selection' | 'complete';

