/**
 * ProblemDetail
 *
 * RFC 7807 Problem Details response for API errors.
 *
 * All error responses follow this standard format, enabling consistent error handling
 * across different clients. The `error_code` field provides a machine-readable identifier
 * for programmatic error handling, while `detail` provides human-readable context.
 *
 * Error codes follow the pattern `{DOMAIN}-{HTTP_STATUS}-{SEQUENCE}`, with a trailing `-R`
 * when the failure is retryable: `SAF-503-003-R` means the identical request, retried after
 * a short backoff, can succeed; `WAL-404-001` means retrying it will get the same answer.
 * Domain prefixes
 * in use today: ACC (account), AGT (agent token), AID (connected agent), ALC (Alchemy
 * webhook), AST (asset),
 * BNK (bank), BUD (budget), CALLER (request credentials), CHA (chat attachment), CHT
 * (chat session), CLI (command-line
 * sign-in & personal access tokens), CON
 * (connector), CRD (card), DMO (deployment-mode card), DYN (Dynamic credential), FAC
 * (facilitator), GATE (feature
 * gate), GEN (general validation), HEALTH (health check), IDT (identity token), INS
 * (insight), IPA (intelligent purchase authorization), KYC (KYC/verification), MCP (Model Context
 * Protocol), MCR (spending-mandate approval), MKY (mandate key), MLD
 * (MELD), MRC (merchant search), OBK (open banking), ONB (onboarding), ORG
 * (organisation), PAY (payment
 * link), PAR (embedded-wallet provider webhook), PFP (profile
 * picture), PHONE (phone verification), PINT (payment intent token), PRV (provider),
 * RCT (receipt), RMP (ramp), RPC (RPC usage), RUL (rule), RUN (strategy
 * run), SAF (Safe smart contract), SGN (signer setup), SIS (Sumvin Integration
 * Services), SIW (Sign-In With Ethereum), SRI (Sumvin Resource Identifier), STR
 * (strategy), STS (user status), SYS (system), TAP (Trusted Agent Protocol), TOL
 * (tool), TXN (transaction), UCO
 * (user connector), USR (user), UST (user strategy), VIC (Visa checkout), WAL
 * (wallet), WID (widget).
 *
 * See the Error Reference section for a complete list of error codes and recovery actions.
 */
export type ProblemDetail = {
    /**
     * Type
     *
     * URI reference identifying the problem type. Format: https://api.sumvin.com/errors/{error_code}
     */
    type: string;
    /**
     * Title
     *
     * Short, human-readable summary of the problem type. Does not change between occurrences.
     */
    title: string;
    /**
     * Status
     *
     * HTTP status code for this error response.
     */
    status: number;
    /**
     * Detail
     *
     * Human-readable explanation specific to this occurrence of the problem.
     */
    detail: string;
    /**
     * Instance
     *
     * URI reference identifying the specific occurrence (typically the request path).
     */
    instance: string;
    /**
     * Machine-readable error code for programmatic handling. Format: {DOMAIN}-{STATUS}-{SEQUENCE}, plus -R when retrying the same request can succeed.
     */
    error_code: ApiErrorCode;
    /**
     * Trace Id
     *
     * Correlation ID for tracing this request. Include when contacting support.
     */
    trace_id?: string | null;
    /**
     * Links
     *
     * Actions that clear this error, keyed by link relation. Present only on errors a caller can act on.
     */
    _links?: {
        [key: string]: Affordance;
    } | null;
};

