/**
 * QuoteData
 *
 * A single ramp quote returned by a provider.
 *
 * Quotes are price-discovery only — the figures here are indicative for the
 * moment the quote was returned and are not a binding offer. To execute a
 * trade, open a widget session via `POST /v0/ramp/sessions`.
 */
export type QuoteData = {
    /**
     * From Asset
     *
     * `Asset.symbol` value the user is paying with. ISO 4217 fiat (e.g. `USD`) for buys, crypto symbol (e.g. `USDC`) for sells.
     */
    from_asset: string;
    /**
     * To Asset
     *
     * `Asset.symbol` value the user is receiving. Crypto for buys, fiat for sells.
     */
    to_asset: string;
    /**
     * Chain Id
     *
     * EIP-155 chain id of the crypto leg, or null when the leg cannot be resolved to a known chain.
     */
    chain_id?: number | null;
    /**
     * Source Amount
     *
     * Amount of `from_asset` the user pays in (echoes the quote request).
     */
    source_amount: string;
    /**
     * Destination Amount
     *
     * Amount of `to_asset` the user receives at the indicative exchange rate, after all fees. Null if the provider did not return one.
     */
    destination_amount?: string | null;
    /**
     * Exchange Rate
     *
     * Indicative `to_asset` per unit of `from_asset` at quote time.
     */
    exchange_rate?: number | null;
    /**
     * Total Fee
     *
     * Total fee bundled into the quote, in `from_asset` units. Sum of `network_fee`, `transaction_fee`, and `partner_fee` where the provider breaks them out.
     */
    total_fee?: string | null;
    /**
     * Network Fee
     *
     * On-chain network fee component, in `from_asset` units. Null when the provider does not break this out.
     */
    network_fee?: string | null;
    /**
     * Transaction Fee
     *
     * Provider's processing fee component, in `from_asset` units. Null when the provider does not break this out.
     */
    transaction_fee?: string | null;
    /**
     * Partner Fee
     *
     * Sumvin's partner fee component, in `from_asset` units. Null when no partner fee applies.
     */
    partner_fee?: string | null;
    /**
     * Payment Method Type
     *
     * Payment rail this quote is for (e.g. `CARD`, `ACH`, `SEPA`). See [Supported values](/products/meld/supported-values#payment-method-types).
     */
    payment_method_type?: string | null;
    /**
     * Service Provider
     *
     * Upstream service provider this quote is from (e.g. `MERCURYO`, `TRANSAK`). Use this value as `service_provider` on `POST /v0/ramp/sessions` to pin the session to the same provider.
     */
    service_provider?: string | null;
    /**
     * Country Code
     *
     * ISO 3166-1 alpha-2 country code the provider quoted against.
     */
    country_code?: string | null;
    /**
     * Ramp Score
     *
     * Provider's heuristic ranking score for this quote within the result set. Higher is better; absent for providers that don't expose ranking.
     */
    ramp_score?: number | null;
    /**
     * Low Kyc
     *
     * True when this quote is available under the provider's reduced-KYC flow. Absent when the provider does not signal a low-KYC tier.
     */
    low_kyc?: boolean | null;
    /**
     * Is Swap
     *
     * True when this route was fulfilled by stitching a fiat ramp with a downstream swap rather than a direct provider route. The swap is fully managed by the upstream provider; `from_asset`/`to_asset` and the fee fields in this response are end-to-end.
     */
    is_swap?: boolean;
};

