/**
 * WalletShareEncryption
 *
 * How the browser encrypted the wallet share, so the same browser can decrypt it.
 *
 * The encryption key is derived in the browser from a passkey's PRF output with
 * HKDF-SHA256 (`prf_salt` as the salt, `hkdf_info` as the info) and never sent to
 * the server. Binary values are unpadded base64url.
 */
export type WalletShareEncryption = {
    /**
     * Version
     *
     * Envelope format version. Always 1.
     */
    version: 1;
    /**
     * Alg
     *
     * Cipher used for the share.
     */
    alg: 'AES-256-GCM';
    /**
     * Kdf
     *
     * How the encryption key is derived from the passkey's PRF output.
     */
    kdf: 'HKDF-SHA256';
    /**
     * Prf Salt
     *
     * Salt passed to HKDF, and the input evaluated by the passkey's PRF. 32 bytes.
     */
    prf_salt: string;
    /**
     * Hkdf Info
     *
     * The `info` string passed to HKDF.
     */
    hkdf_info: string;
    /**
     * Iv
     *
     * AES-GCM nonce the share was encrypted under. 12 bytes.
     */
    iv: string;
    /**
     * Credential Id
     *
     * ID of the passkey whose PRF output derives the key. 16 to 1023 bytes.
     */
    credential_id: string;
};

/**
 * WalletShareEncryptionData
 *
 * How the stored share was encrypted, exactly as the browser sent it when binding.
 *
 * Returned as stored, without re-checking it against the bind request's rules, so
 * a share bound under earlier rules can still be read back.
 */
export type WalletShareEncryptionData = {
    /**
     * Version
     *
     * Envelope format version.
     */
    version: number;
    /**
     * Alg
     *
     * Cipher used for the share.
     */
    alg: string;
    /**
     * Kdf
     *
     * How the encryption key is derived from the passkey's PRF output.
     */
    kdf: string;
    /**
     * Prf Salt
     *
     * Salt passed to HKDF, and the input evaluated by the passkey's PRF. Unpadded base64url.
     */
    prf_salt: string;
    /**
     * Hkdf Info
     *
     * The `info` string passed to HKDF.
     */
    hkdf_info: string;
    /**
     * Iv
     *
     * AES-GCM nonce the share was encrypted under. Unpadded base64url.
     */
    iv: string;
    /**
     * Credential Id
     *
     * ID of the passkey whose PRF output derives the key. Unpadded base64url.
     */
    credential_id: string;
};

/**
 * WalletSignerCreateRequest
 *
 * Request payload for registering an additional signer on a Safe.
 */
export type WalletSignerCreateRequest = {
    /**
     * New Owner Address
     *
     * Address to register as a signer on the Safe. Must be an address the caller controls the key for — it is not verified here, and it will be able to authorise actions on the Safe once registered. Accepted in either checksummed or lowercase form.
     */
    new_owner_address: string;
};

/**
 * WalletSignerRegistrationLinks
 *
 * Links on an accepted signer registration.
 *
 * The registration answers before the owner addition has happened, so the
 * link that matters is the one that says where the outcome will appear.
 * `signer-status` is a separate rel from `self` on purpose: `self` is the
 * collection the request was posted to, and following it again would start a
 * second registration rather than read the first one's result.
 */
export type WalletSignerRegistrationLinks = {
    /**
     * URL to the current resource.
     */
    self: Link;
    /**
     * Read the registration's current state; poll until it settles.
     */
    'signer-status'?: Link | null;
    /**
     * The Safe the signer is being added to.
     */
    wallet?: Link | null;
    [key: string]: unknown;
};

/**
 * WalletSignerRegistrationResponse
 *
 * An accepted request to register an additional signer on a Safe.
 *
 * Returned before the owner addition has been attempted on chain, so the only
 * settled fact here is that the registration was recorded. `id` is the wallet
 * resource the registered address now has — reading it back is how a client
 * learns whether the addition landed.
 */
export type WalletSignerRegistrationResponse = {
    /**
     * HAL-style hypermedia links for navigation.
     */
    _links: WalletSignerRegistrationLinks;
    /**
     * Id
     *
     * Public identifier of the registered address's wallet record. Read it at `GET /v0/wallets/{id}` to follow the registration.
     */
    id: string;
    /**
     * Address
     *
     * The address being registered, in lowercase.
     */
    address: string;
    /**
     * Chain Id
     *
     * Chain the Safe is deployed on.
     */
    chain_id: number;
    /**
     * State of the registration at the moment it was accepted. Always `pending` here; the settled value appears on the wallet resource.
     */
    signer_status: MandateKeyStatus;
};

